import React,{useState} from 'react';import {createRoot} from 'react-dom/client';
import {CreatorRollBridge} from '../../apps/room3d/chibi/CreatorRollBridge';import {decodeParts,createVisitor} from '../../apps/room3d/chibi/visitor';import {mountHomeEditor} from '../../apps/room3d/editor.js';import {createHome} from '../../apps/room3d/model.js';import {SHOWROOMS,furnishShowroom} from '../../apps/room3d/showrooms.js';import {setBoundary} from '../../apps/room3d/topology.js';import '../../apps/room3d/editor.css';
function Fixture(){const [request,setRequest]=useState(0);return <><div id="home"/><CreatorRollBridge request={request} onReady={()=>setRequest(1)} onError={console.error} onResult={async result=>{const w=window as any;if(w.__loading)return;w.__loading=true;const c=await fetch('/room3d/catalog.json').then(r=>r.json()),q=new URLSearchParams(location.search),kind=q.get('room')||'living',key=q.has('fresh')?'showrooms-preview-storage-'+kind:'showrooms-qa';let home=JSON.parse(localStorage.getItem(key)||'null');if(!home){home=createHome(c);home.rooms[0].items=[];if(!q.has('empty')){furnishShowroom(home.rooms[0],kind,c);setBoundary(home,home.rooms[0].id,'front',{kind:'wall_high',door:{kind:SHOWROOMS[kind].door,at:0,width:2.2}},c);}}const e=await mountHomeEditor(document.querySelector('#home')!,{assetBase:new URL('/room3d/',location.href).href,initialState:home,storageKey:key});const visitor=await createVisitor(await decodeParts(result),q.has('blank')?{layers:{},extras:[],bodyShape:'blank'}:undefined);e.setVisitor!(visitor);w.__visitor=visitor;w.__homeEditor=e;w.render_game_to_text=()=>JSON.stringify(e.inspect!());w.advanceTime=(ms:number)=>e.advanceTime!(ms);}}/></>;}createRoot(document.querySelector('#root')!).render(<Fixture/>);
